        let planePos = { x: 0, y: 0, z: 0 };
        let planeVel = { x: 0, y: 0, z: 0 };
        let planeRot = { x: 0, y: 0, z: 0 };

        // --- PARTICLES ---
        interface Particle {
            x: number; y: number; z: number;
            vx: number; vy: number; vz: number;
            life: number;
            color: string;
            type: 'data' | 'trail' | 'ember';
